ont-bold">Reference Number<input name="reference" value="{{old('reference')}}" class="mt-1.5 h-12 w-full rounded-xl border-2 border-slate-200 px-3" placeholder="Optional reference"></label><label class="text-sm font-bold xl:col-span-2">Reason / Note<input name="note" value="{{old('note')}}" class="mt-1.5 h-12 w-full rounded-xl border-2 border-slate-200 px-3" placeholder="Why is this money being moved?"></label><div class="flex gap-2 xl:col-start-4"><button class="h-12 flex-1 rounded-xl bg-red-500 font-black text-white">Save Transfer</button><button type="reset" class="h-12 rounded-xl border-2 border-slate-200 px-5 font-bold">Clear Form</button></div></form></section>
